            if start < cut:
                result.append((start, cut))
            start = cut + 1
        if start < size:
            result.append((start, size))
        return result

    row_bands = spans(h, row_seps)
    col_bands = spans(w, col_seps)

    # The partial-height final band is not part of the pattern.
    full_height = max(b - a for a, b in row_bands)

    for r0, r1 in row_bands:
        if r1 - r0 != full_height:
            continue

        for left in range(0, len(col_bands) - 1, 2):
            c0, c1 = col_bands[left]
            d0, d1 = col_bands[left + 1]
            if c1 - c0 != d1 - d0:
                continue

            left_cells = [
                (r, c) for r in range(r0, r1) for c in range(c0, c1)
                if grid[r][c] not in (0, grid[row_seps[0]][0] if row_seps else -1)
            ]
            right_cells = [
                (r, c) for r in range(r0, r1) for c in range(d0, d1)
                if grid[r][c] not in (0, grid[row_seps[0]][0] if row_seps else -1)
            ]

            # Copy the occupied panel into its blank partner, reflected horizontally.
            if left_cells and not right_cells:
                for r, c in left_cells:
                    out[r][d0 + (c1 - 1 - c - c0)] = grid[r][c]
            elif right_cells and not left_cells:
                for r, c in right_cells:
                    out[r][c0 + (d1 - 1 - c - d0)] = grid[r][c]

    return out
