def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    row_seps = [
        r for r in range(h)
        if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])
    ]
    col_seps = [
        c for c in range(w)
        if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))
    ]

    def bands(size, cuts):
        result = []
        start = 0
        for cut in cuts:
            if start < cut:
                result.append((start, cut))
            start = cut + 1
        if start < size:
            result.append((start, size))
        return result

    rb = bands(h, row_seps)
    cb = bands(w, col_seps)
    if not rb or not cb:
        return out

    # Ignore any incomplete edge bands.
    rh = max(b - a for a, b in rb)
    cw = max(b - a for a, b in cb)
    rb = [(a, b) for a, b in rb if b - a == rh]
    cb = [(a, b) for a, b in cb if b - a == cw]

    sep_color = grid[row_seps[0]][0] if row_seps else (
        grid[0][col_seps[0]] if col_seps else None
    )
    colors = {v for row in grid for v in row if v != 0 and v != sep_color}

    def shape(color, band, colband):
        r0, r1 = band
        c0, c1 = colband
        return frozenset(
            (r - r0, c - c0)
            for r in range(r0, r1)
            for c in range(c0, c1)
            if grid[r][c] == color
        )

    for color in colors:
        # Find the adjacent column pair that contains horizontally mirrored
        # instances of this color in at least one row band.
        best_pair = None
        best_score = 0
        for j in range(len(cb) - 1):
            score = 0
            for band in rb:
                a = shape(color, band, cb[j])
                b = shape(color, band, cb[j + 1])
                if a and b:
                    reflected = frozenset((r, cw - 1 - c) for r, c in a)
                    if reflected == b:
                        score += 1
            if score > best_score:
                best_score = score
                best_pair = j

        if best_pair is None:
            continue

        j = best_pair
        for band in rb:
            left = shape(color, band, cb[j])
            right = shape(color, band, cb[j + 1])
            if bool(left) == bool(right):
                continue

            r0 = band[0]
            if left:
                c0 = cb[j + 1][0]
                for r, c in left:
                    out[r0 + r][c0 + cw - 1 - c] = color
            else:
                c0 = cb[j][0]
                for r, c in right:
                    out[r0 + r][c0 + cw - 1 - c] = color

    return out
